-- TPC-DS Test_Query Query 375
-- Based on: query48.tpl (medium)
-- Variation: 50

select sum (ss_quantity) from store_sales, store, customer_demographics, customer_address, date_dim where s_store_sk = ss_store_sk and  ss_sold_date_sk = d_date_sk and d_year = 1944 and ( ( cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.2' and cd_education_status = 'ES.3' and ss_sales_price between 100.2 and 150.2 ) or ( cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.2' and cd_education_status = 'ES.1' and ss_sales_price between 50.2 and 100.1 ) or ( cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.5' and cd_education_status = 'ES.1' and ss_sales_price between 150.1 and 200.1 ) ) and ( ( ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.1', 'STATE.1', 'STATE.3') and ss_net_profit between 2 and 2024 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.5', 'STATE.7', 'STATE.4') and ss_net_profit between 155 and 2998 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.9', 'STATE.9', 'STATE.9') and ss_net_profit between 48 and 25000 ) );
